     1→/**
     2→ * FreeLang Nexus - WebAssembly (WAT) 코드 생성 단위 테스트
     3→ *
     4→ * Phase N.4 WebAssembly 지원 — 접근법 B: AST → WAT 직접 생성
     5→ *
     6→ * 테스트 범위:
     7→ *  1. 기본 함수 생성 (module/func/export 구조)
     8→ *  2. 파라미터 & 반환 타입 변환
     9→ *  3. 산술/비교 이항 연산자
    10→ *  4. 지역 변수 선언 및 할당
    11→ *  5. if/else 조건문
    12→ *  6. while 루프 (break/continue 포함)
    13→ *  7. for-in range 루프
    14→ *  8. 재귀 함수 호출
    15→ *  9. Python 모드 / 미지원 타입 경고
    16→ * 10. 다중 함수 & 다중 export
    17→ */
    18→
    19→import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
    20→import { NexusParser } from '../src/nexus/parser/nexus-parser';
    21→import { NexusWasmCodegen, WasmCodegenResult } from '../src/nexus/codegen/nexus-wasm-codegen';
    22→
    23→// ─── 헬퍼 ────────────────────────────────────────────────────────────────────
    24→
    25→function compileWat(code: string): WasmCodegenResult {
    26→  const lexer = new NexusLexer(code);
    27→  const tokens = lexer.tokenize();
    28→  const parser = new NexusParser(tokens);
    29→  const ast = parser.parse();
    30→  const gen = new NexusWasmCodegen();
    31→  return gen.generate(ast);
    32→}
    33→
    34→function wat(code: string): string {
    35→  return compileWat(code).wat;
    36→}
    37→
    38→// ─── 1. 기본 구조 ─────────────────────────────────────────────────────────────
    39→
    40→describe('WAT 코드 생성 - 기본 모듈 구조', () => {
    41→  test('Test 1: module 래퍼 생성', () => {
    42→    const result = wat(`@mode(v)
    43→fn add(a: i64, b: i64) -> i64 {
    44→  return a + b
    45→}`);
    46→    expect(result).toContain('(module');
    47→    // 마지막 줄은 닫는 괄호
    48→    const lines = result.trim().split('\n');
    49→    expect(lines[lines.length - 1].trim()).toBe(')');
    50→  });
    51→
    52→  test('Test 2: func 키워드와 함수명 생성', () => {
    53→    const result = wat(`@mode(v)
    54→fn add(a: i64, b: i64) -> i64 {
    55→  return a + b
    56→}`);
    57→    expect(result).toContain('(func $add');
    58→  });
    59→
    60→  test('Test 3: export 선언 생성', () => {
    61→    const result = wat(`@mode(v)
    62→fn add(a: i64, b: i64) -> i64 {
    63→  return a + b
    64→}`);
    65→    expect(result).toContain('(export "add" (func $add))');
    66→  });
    67→
    68→  test('Test 4: exports 배열에 함수명 포함', () => {
    69→    const result = compileWat(`@mode(v)
    70→fn multiply(x: i64, y: i64) -> i64 {
    71→  return x * y
    72→}`);
    73→    expect(result.exports).toContain('multiply');
    74→  });
    75→
    76→  test('Test 5: 빈 V 함수 경고 없음', () => {
    77→    const result = compileWat(`@mode(v)
    78→fn noop() -> i64 {
    79→  return 0
    80→}`);
    81→    // 경고 없어야 함 (미지원 기능 없음)
    82→    const criticalWarnings = result.warnings.filter(w =>
    83→      !w.includes('host import') && !w.includes('미지원')
    84→    );
    85→    expect(criticalWarnings.length).toBe(0);
    86→  });
    87→});
    88→
    89→// ─── 2. 타입 변환 ─────────────────────────────────────────────────────────────
    90→
    91→describe('WAT 코드 생성 - 타입 매핑', () => {
    92→  test('Test 6: i64 파라미터 타입 변환', () => {
    93→    const result = wat(`@mode(v)
    94→fn add(a: i64, b: i64) -> i64 {
    95→  return a + b
    96→}`);
    97→    expect(result).toContain('(param $a i64)');
    98→    expect(result).toContain('(param $b i64)');
    99→  });
   100→
   101→  test('Test 7: i64 반환 타입 변환', () => {
   102→    const result = wat(`@mode(v)
   103→fn add(a: i64, b: i64) -> i64 {
   104→  return a + b
   105→}`);
   106→    expect(result).toContain('(result i64)');
   107→  });
   108→
   109→  test('Test 8: f64 파라미터 타입 변환', () => {
   110→    const result = wat(`@mode(v)
   111→fn mul(x: f64, y: f64) -> f64 {
   112→  return x * y
   113→}`);
   114→    expect(result).toContain('(param $x f64)');
   115→    expect(result).toContain('(param $y f64)');
   116→    expect(result).toContain('(result f64)');
   117→  });
   118→
   119→  test('Test 9: bool 파라미터 → i32 변환', () => {
   120→    const result = wat(`@mode(v)
   121→fn check(flag: bool) -> bool {
   122→  return flag
   123→}`);
   124→    expect(result).toContain('(param $flag i32)');
   125→    expect(result).toContain('(result i32)');
   126→  });
   127→
   128→  test('Test 10: 타입 없는 파라미터 → i64 기본값', () => {
   129→    const result = wat(`@mode(v)
   130→fn identity(x: i64) -> i64 {
   131→  return x
   132→}`);
   133→    expect(result).toContain('(param $x i64)');
   134→  });
   135→});
   136→
   137→// ─── 3. 산술 연산자 ───────────────────────────────────────────────────────────
   138→
   139→describe('WAT 코드 생성 - 산술/비교 연산자', () => {
   140→  test('Test 11: 덧셈 → i64.add', () => {
   141→    const result = wat(`@mode(v)
   142→fn add(a: i64, b: i64) -> i64 {
   143→  return a + b
   144→}`);
   145→    expect(result).toContain('i64.add');
   146→  });
   147→
   148→  test('Test 12: 뺄셈 → i64.sub', () => {
   149→    const result = wat(`@mode(v)
   150→fn sub(a: i64, b: i64) -> i64 {
   151→  return a - b
   152→}`);
   153→    expect(result).toContain('i64.sub');
   154→  });
   155→
   156→  test('Test 13: 곱셈 → i64.mul', () => {
   157→    const result = wat(`@mode(v)
   158→fn mul(a: i64, b: i64) -> i64 {
   159→  return a * b
   160→}`);
   161→    expect(result).toContain('i64.mul');
   162→  });
   163→
   164→  test('Test 14: 나눗셈 → i64.div_s', () => {
   165→    const result = wat(`@mode(v)
   166→fn div(a: i64, b: i64) -> i64 {
   167→  return a / b
   168→}`);
   169→    expect(result).toContain('i64.div_s');
   170→  });
   171→
   172→  test('Test 15: 같음 비교 → i64.eq', () => {
   173→    const result = wat(`@mode(v)
   174→fn eq(a: i64, b: i64) -> i64 {
   175→  return a == b
   176→}`);
   177→    expect(result).toContain('i64.eq');
   178→  });
   179→
   180→  test('Test 16: 작음 비교 → i64.lt_s', () => {
   181→    const result = wat(`@mode(v)
   182→fn lt(a: i64, b: i64) -> i64 {
   183→  return a < b
   184→}`);
   185→    expect(result).toContain('i64.lt_s');
   186→  });
   187→
   188→  test('Test 17: 큼 비교 → i64.gt_s', () => {
   189→    const result = wat(`@mode(v)
   190→fn gt(a: i64, b: i64) -> i64 {
   191→  return a > b
   192→}`);
   193→    expect(result).toContain('i64.gt_s');
   194→  });
   195→});
   196→
   197→// ─── 4. 로컬 변수 ─────────────────────────────────────────────────────────────
   198→
   199→describe('WAT 코드 생성 - 로컬 변수', () => {
   200→  test('Test 18: let 변수 → (local ...) 선언', () => {
   201→    const result = wat(`@mode(v)
   202→fn test() -> i64 {
   203→  let x = 42
   204→  return x
   205→}`);
   206→    expect(result).toContain('(local $x i64)');
   207→  });
   208→
   209→  test('Test 19: 변수 할당 → local.set', () => {
   210→    const result = wat(`@mode(v)
   211→fn test() -> i64 {
   212→  let x = 42
   213→  return x
   214→}`);
   215→    expect(result).toContain('local.set $x');
   216→  });
   217→
   218→  test('Test 20: 변수 읽기 → local.get', () => {
   219→    const result = wat(`@mode(v)
   220→fn test() -> i64 {
   221→  let x = 42
   222→  return x
   223→}`);
   224→    expect(result).toContain('local.get $x');
   225→  });
   226→
   227→  test('Test 21: 정수 리터럴 → i64.const', () => {
   228→    const result = wat(`@mode(v)
   229→fn test() -> i64 {
   230→  let x = 100
   231→  return x
   232→}`);
   233→    expect(result).toContain('i64.const 100');
   234→  });
   235→
   236→  test('Test 22: 파라미터 변수 읽기 → local.get', () => {
   237→    const result = wat(`@mode(v)
   238→fn double(n: i64) -> i64 {
   239→  return n + n
   240→}`);
   241→    // n을 두 번 참조
   242→    const count = (result.match(/local\.get \$n/g) || []).length;
   243→    expect(count).toBe(2);
   244→  });
   245→});
   246→
   247→// ─── 5. if/else 조건문 ────────────────────────────────────────────────────────
   248→
   249→describe('WAT 코드 생성 - if/else', () => {
   250→  test('Test 23: if 블록 → (if (then ...))', () => {
   251→    const result = wat(`@mode(v)
   252→fn test(x: i64) -> i64 {
   253→  if x > 0 {
   254→    return x
   255→  }
   256→  return 0
   257→}`);
   258→    expect(result).toContain('(if');
   259→    expect(result).toContain('(then');
   260→  });
   261→
   262→  test('Test 24: if/else 블록 → (if (then ...) (else ...))', () => {
   263→    const result = wat(`@mode(v)
   264→fn abs_val(x: i64) -> i64 {
   265→  if x >= 0 {
   266→    return x
   267→  } else {
   268→    return 0
   269→  }
   270→}`);
   271→    expect(result).toContain('(if');
   272→    expect(result).toContain('(then');
   273→    expect(result).toContain('(else');
   274→  });
   275→
   276→  test('Test 25: if 조건 표현식이 스택에 push됨', () => {
   277→    const result = wat(`@mode(v)
   278→fn test(x: i64) -> i64 {
   279→  if x > 5 {
   280→    return 1
   281→  }
   282→  return 0
   283→}`);
   284→    // 조건: x > 5 → local.get $x, i64.const 5, i64.gt_s
   285→    expect(result).toContain('local.get $x');
   286→    expect(result).toContain('i64.const 5');
   287→    expect(result).toContain('i64.gt_s');
   288→  });
   289→});
   290→
   291→// ─── 6. while 루프 ────────────────────────────────────────────────────────────
   292→
   293→describe('WAT 코드 생성 - while 루프', () => {
   294→  test('Test 26: while 루프 → block/loop 구조', () => {
   295→    const result = wat(`@mode(v)
   296→fn test() -> i64 {
   297→  let i = 0
   298→  while i < 10 {
   299→    i = i + 1
   300→  }
   301→  return i
   302→}`);
   303→    expect(result).toContain('(block');
   304→    expect(result).toContain('(loop');
   305→  });
   306→
   307→  test('Test 27: while 루프 → br_if 탈출 조건', () => {
   308→    const result = wat(`@mode(v)
   309→fn test() -> i64 {
   310→  let i = 0
   311→  while i < 10 {
   312→    i = i + 1
   313→  }
   314→  return i
   315→}`);
   316→    expect(result).toContain('br_if');
   317→    expect(result).toContain('i32.eqz');
   318→  });
   319→
   320→  test('Test 28: while 루프 → br (back-edge)', () => {
   321→    const result = wat(`@mode(v)
   322→fn test() -> i64 {
   323→  let i = 0
   324→  while i < 5 {
   325→    i = i + 1
   326→  }
   327→  return i
   328→}`);
   329→    // loop 끝에서 back-edge br
   330→    expect(result).toContain('br $while_inner_0');
   331→  });
   332→
   333→  test('Test 29: break → br 외부 블록', () => {
   334→    const result = wat(`@mode(v)
   335→fn test() -> i64 {
   336→  let i = 0
   337→  while 1 {
   338→    if i == 5 {
   339→      break
   340→    }
   341→    i = i + 1
   342→  }
   343→  return i
   344→}`);
   345→    expect(result).toContain('br $while_outer_0');
   346→  });
   347→
   348→  test('Test 30: continue → br 루프 상단', () => {
   349→    const result = wat(`@mode(v)
   350→fn test() -> i64 {
   351→  let i = 0
   352→  while i < 10 {
   353→    i = i + 1
   354→    if i == 3 {
   355→      continue
   356→    }
   357→  }
   358→  return i
   359→}`);
   360→    expect(result).toContain('br $while_inner_0');
   361→  });
   362→});
   363→
   364→// ─── 7. for-in range 루프 ─────────────────────────────────────────────────────
   365→
   366→describe('WAT 코드 생성 - for-in range 루프', () => {
   367→  test('Test 31: for 루프 → block/loop 구조', () => {
   368→    const result = wat(`@mode(v)
   369→fn sum() -> i64 {
   370→  let s = 0
   371→  for i in range(10) {
   372→    s = s + i
   373→  }
   374→  return s
   375→}`);
   376→    expect(result).toContain('(block');
   377→    expect(result).toContain('(loop');
   378→  });
   379→
   380→  test('Test 32: for 루프 변수 초기화 → i64.const 0 + local.set', () => {
   381→    const result = wat(`@mode(v)
   382→fn test() -> i64 {
   383→  for i in range(5) {
   384→  }
   385→  return 0
   386→}`);
   387→    expect(result).toContain('i64.const 0');
   388→    expect(result).toContain('local.set $i');
   389→  });
   390→
   391→  test('Test 33: for 루프 변수 → (local $i i64) 선언', () => {
   392→    const result = wat(`@mode(v)
   393→fn test() -> i64 {
   394→  for i in range(5) {
   395→  }
   396→  return 0
   397→}`);
   398→    expect(result).toContain('(local $i i64)');
   399→  });
   400→
   401→  test('Test 34: for 루프 상한 비교 → i64.ge_s + br_if', () => {
   402→    const result = wat(`@mode(v)
   403→fn test() -> i64 {
   404→  for i in range(100) {
   405→  }
   406→  return 0
   407→}`);
   408→    expect(result).toContain('i64.ge_s');
   409→    expect(result).toContain('br_if');
   410→  });
   411→
   412→  test('Test 35: for 루프 증가 → i64.add + local.set', () => {
   413→    const result = wat(`@mode(v)
   414→fn test() -> i64 {
   415→  for i in range(5) {
   416→  }
   417→  return 0
   418→}`);
   419→    expect(result).toContain('i64.const 1');
   420→    expect(result).toContain('i64.add');
   421→  });
   422→});
   423→
   424→// ─── 8. 함수 호출 ─────────────────────────────────────────────────────────────
   425→
   426→describe('WAT 코드 생성 - 함수 호출', () => {
   427→  test('Test 36: 사용자 정의 함수 호출 → call $name', () => {
   428→    const result = wat(`@mode(v)
   429→fn add(a: i64, b: i64) -> i64 {
   430→  return a + b
   431→}
   432→fn main() -> i64 {
   433→  return add(1, 2)
   434→}`);
   435→    expect(result).toContain('call $add');
   436→  });
   437→
   438→  test('Test 37: 재귀 함수 호출 → call $self', () => {
   439→    const result = wat(`@mode(v)
   440→fn fact(n: i64) -> i64 {
   441→  if n <= 1 {
   442→    return 1
   443→  }
   444→  return n * fact(n)
   445→}`);
   446→    expect(result).toContain('call $fact');
   447→  });
   448→
   449→  test('Test 38: 함수 인자 스택에 push됨', () => {
   450→    const result = wat(`@mode(v)
   451→fn add(a: i64, b: i64) -> i64 {
   452→  return a + b
   453→}
   454→fn main() -> i64 {
   455→  return add(3, 7)
   456→}`);
   457→    // 인자 3, 7이 push되어야 함
   458→    expect(result).toContain('i64.const 3');
   459→    expect(result).toContain('i64.const 7');
   460→  });
   461→});
   462→
   463→// ─── 9. 다중 함수 & export ────────────────────────────────────────────────────
   464→
   465→describe('WAT 코드 생성 - 다중 함수', () => {
   466→  test('Test 39: 다중 V 함수 모두 export', () => {
   467→    const result = compileWat(`@mode(v)
   468→fn add(a: i64, b: i64) -> i64 {
   469→  return a + b
   470→}
   471→fn sub(a: i64, b: i64) -> i64 {
   472→  return a - b
   473→}
   474→fn mul(a: i64, b: i64) -> i64 {
   475→  return a * b
   476→}`);
   477→    expect(result.exports).toContain('add');
   478→    expect(result.exports).toContain('sub');
   479→    expect(result.exports).toContain('mul');
   480→    expect(result.exports.length).toBe(3);
   481→  });
   482→
   483→  test('Test 40: 다중 함수 WAT에 모두 포함', () => {
   484→    const result = wat(`@mode(v)
   485→fn add(a: i64, b: i64) -> i64 {
   486→  return a + b
   487→}
   488→fn sub(a: i64, b: i64) -> i64 {
   489→  return a - b
   490→}`);
   491→    expect(result).toContain('(func $add');
   492→    expect(result).toContain('(func $sub');
   493→    expect(result).toContain('(export "add"');
   494→    expect(result).toContain('(export "sub"');
   495→  });
   496→});
   497→
   498→// ─── 10. Python 모드 & 경고 ───────────────────────────────────────────────────
   499→
   500→describe('WAT 코드 생성 - Python 모드 & 경고', () => {
   501→  test('Test 41: Python 모드 함수 → 경고 기록', () => {
   502→    const result = compileWat(`@mode(python)
   503→def slow(items):
   504→  return items`);
   505→    expect(result.warnings.some(w => w.includes('Python 모드') || w.includes('미지원'))).toBe(true);
   506→  });
   507→
   508→  test('Test 42: 빈 프로그램 → 빈 module 생성', () => {
   509→    const result = wat(`@mode(v)
   510→fn empty() -> i64 {
   511→  return 0
   512→}`);
   513→    expect(result).toContain('(module');
   514→    expect(result.trim().endsWith(')')).toBe(true);
   515→  });
   516→
   517→  test('Test 43: WAT 결과는 문자열', () => {
   518→    const result = compileWat(`@mode(v)
   519→fn noop() -> i64 {
   520→  return 0
   521→}`);
   522→    expect(typeof result.wat).toBe('string');
   523→    expect(result.wat.length).toBeGreaterThan(0);
   524→  });
   525→
   526→  test('Test 44: exports는 배열', () => {
   527→    const result = compileWat(`@mode(v)
   528→fn test() -> i64 {
   529→  return 1
   530→}`);
   531→    expect(Array.isArray(result.exports)).toBe(true);
   532→  });
   533→
   534→  test('Test 45: warnings는 배열', () => {
   535→    const result = compileWat(`@mode(v)
   536→fn test() -> i64 {
   537→  return 1
   538→}`);
   539→    expect(Array.isArray(result.warnings)).toBe(true);
   540→  });
   541→});
