     1→/**
     2→ * FreeLang Nexus - WebAssembly Text Format (WAT) 코드 생성기
     3→ *
     4→ * Phase N.4 WebAssembly 지원
     5→ * 접근법 B: FreeLang V 모드 AST → WAT (WebAssembly Text Format) 직접 생성
     6→ *
     7→ * 지원 대상:
     8→ *  - V 모드 함수 (fn ... -> ...)
     9→ *  - 기본 타입: i64, f64, bool (i32), string은 미지원(메모리 필요)
    10→ *  - 산술/비교 이항 연산자
    11→ *  - 지역 변수 (let)
    12→ *  - return 문
    13→ *  - if/else 분기
    14→ *  - while 루프
    15→ *  - 재귀 함수 호출
    16→ *
    17→ * WAT 출력 예시:
    18→ *   (module
    19→ *     (func $add (param $a i64) (param $b i64) (result i64)
    20→ *       local.get $a
    21→ *       local.get $b
    22→ *       i64.add)
    23→ *     (export "add" (func $add)))
    24→ */
    25→
    26→import * as AST from '../parser/ast';
    27→
    28→// ─── 타입 매핑 ────────────────────────────────────────────────────────────────
    29→
    30→/** FreeLang 타입 → WASM 타입 */
    31→function toWasmType(flType: string | undefined): string {
    32→  if (!flType) return 'i64'; // 기본값
    33→  switch (flType.trim()) {
    34→    case 'i64': return 'i64';
    35→    case 'f64': return 'f64';
    36→    case 'f32': return 'f32';
    37→    case 'i32': return 'i32';
    38→    case 'bool': return 'i32'; // bool → i32 (WASM에 bool 없음)
    39→    case 'void': return '';    // 반환 없음
    40→    default: return 'i64';     // 미지원 타입은 i64 폴백
    41→  }
    42→}
    43→
    44→/** WASM 타입별 산술 연산 opcode */
    45→function wasmBinOp(op: string, wasmType: string): string {
    46→  const t = wasmType === '' ? 'i64' : wasmType;
    47→  switch (op) {
    48→    case '+':  return `${t}.add`;
    49→    case '-':  return `${t}.sub`;
    50→    case '*':  return `${t}.mul`;
    51→    case '/':  return t.startsWith('f') ? `${t}.div` : `${t}.div_s`;
    52→    case '%':  return t.startsWith('f') ? `${t}.rem_f` : `${t}.rem_s`;
    53→    case '==': return t.startsWith('f') ? `${t}.eq` : `${t}.eq`;
    54→    case '!=': return t.startsWith('f') ? `${t}.ne` : `${t}.ne`;
    55→    case '<':  return t.startsWith('f') ? `${t}.lt` : `${t}.lt_s`;
    56→    case '>':  return t.startsWith('f') ? `${t}.gt` : `${t}.gt_s`;
    57→    case '<=': return t.startsWith('f') ? `${t}.le` : `${t}.le_s`;
    58→    case '>=': return t.startsWith('f') ? `${t}.ge` : `${t}.ge_s`;
    59→    case '&&': return 'i32.and';
    60→    case '||': return 'i32.or';
    61→    default:   return `i64.add`; // 폴백
    62→  }
    63→}
    64→
    65→// ─── 코드 생성기 ──────────────────────────────────────────────────────────────
    66→
    67→export interface WasmCodegenResult {
    68→  /** WAT (WebAssembly Text Format) 텍스트 */
    69→  wat: string;
    70→  /** export된 함수 이름 목록 */
    71→  exports: string[];
    72→  /** 경고 메시지 (미지원 기능 등) */
    73→  warnings: string[];
    74→}
    75→
    76→/**
    77→ * FreeLang V 모드 AST → WAT 코드 생성기
    78→ *
    79→ * 사용 예:
    80→ *   const gen = new NexusWasmCodegen();
    81→ *   const result = gen.generate(program);
    82→ *   // result.wat → .wat 파일로 저장 후 wat2wasm으로 컴파일
    83→ */
    84→export class NexusWasmCodegen {
    85→  private lines: string[] = [];
    86→  private indentLevel: number = 0;
    87→  private exports: string[] = [];
    88→  private warnings: string[] = [];
    89→  /** 현재 함수의 로컬 변수 타입 맵 */
    90→  private localTypes: Map<string, string> = new Map();
    91→  /** 현재 함수의 파라미터 목록 (local.get 구분용) */
    92→  private paramNames: Set<string> = new Set();
    93→  /** break/continue 구현용 블록 레이블 스택 */
    94→  private loopLabelStack: { breakLabel: string; continueLabel: string }[] = [];
    95→  private loopCounter: number = 0;
    96→
    97→  // ─── 공개 인터페이스 ─────────────────────────────────────────────────────────
    98→
    99→  /**
   100→   * Program AST → WAT 생성
   101→   * Python 모드 함수, LangBlock 등은 스킵 (경고만 기록)
   102→   */
   103→  generate(program: AST.Program): WasmCodegenResult {
   104→    this.reset();
   105→
   106→    // module 시작
   107→    this.emit('(module');
   108→    this.indentLevel++;
   109→
   110→    let hasFunctions = false;
   111→    for (const node of program.body) {
   112→      const n = node as any;
   113→      if (n.type === 'VFunction') {
   114→        this.genVFunction(n as AST.VFunction);
   115→        hasFunctions = true;
   116→      } else if (n.type === 'PyFunction') {
   117→        this.warnings.push(`Python 모드 함수 '${(n as AST.PyFunction).name}'은 WASM 미지원 (스킵)`);
   118→      } else if (n.type === 'StructDef') {
   119→        this.warnings.push(`구조체 '${(n as AST.StructDef).name}'은 현재 WASM 미지원 (스킵)`);
   120→      } else if (n.type === 'LangBlock') {
   121→        this.warnings.push(`@lang 블록은 WASM 미지원 (스킵)`);
   122→      } else if (n.type === 'ExternCall') {
   123→        this.warnings.push(`@call 지시문은 WASM 미지원 (스킵)`);
   124→      }
   125→      // 그 외 탑레벨 구문은 무시
   126→    }
   127→
   128→    if (!hasFunctions) {
   129→      this.warnings.push('V 모드 함수가 없습니다. 빈 모듈이 생성됩니다.');
   130→    }
   131→
   132→    this.indentLevel--;
   133→    this.emit(')');
   134→
   135→    return {
   136→      wat: this.lines.join('\n'),
   137→      exports: [...this.exports],
   138→      warnings: [...this.warnings],
   139→    };
   140→  }
   141→
   142→  // ─── 내부 헬퍼 ──────────────────────────────────────────────────────────────
   143→
   144→  private reset(): void {
   145→    this.lines = [];
   146→    this.indentLevel = 0;
   147→    this.exports = [];
   148→    this.warnings = [];
   149→    this.localTypes = new Map();
   150→    this.paramNames = new Set();
   151→    this.loopLabelStack = [];
   152→    this.loopCounter = 0;
   153→  }
   154→
   155→  private emit(line: string): void {
   156→    const indent = '  '.repeat(this.indentLevel);
   157→    this.lines.push(indent + line);
   158→  }
   159→
   160→  private indent(): void  { this.indentLevel++; }
   161→  private dedent(): void  { this.indentLevel = Math.max(0, this.indentLevel - 1); }
   162→
   163→  // ─── 함수 생성 ───────────────────────────────────────────────────────────────
   164→
   165→  private genVFunction(fn: AST.VFunction): void {
   166→    // 상태 초기화
   167→    this.localTypes = new Map();
   168→    this.paramNames = new Set();
   169→    this.loopLabelStack = [];
   170→    this.loopCounter = 0;
   171→
   172→    // 파라미터 타입 수집
   173→    const paramParts = fn.params.map(p => {
   174→      const wt = toWasmType(p.typeAnnotation);
   175→      this.paramNames.add(p.name);
   176→      this.localTypes.set(p.name, wt || 'i64');
   177→      return `(param $${p.name} ${wt || 'i64'})`;
   178→    });
   179→
   180→    // 반환 타입
   181→    const retWasmType = toWasmType(fn.returnType);
   182→    const resultPart = retWasmType ? `(result ${retWasmType})` : '';
   183→
   184→    // 함수 시그니처 첫 줄
   185→    const sigParts = [`(func $${fn.name}`, ...paramParts];
   186→    if (resultPart) sigParts.push(resultPart);
   187→    this.emit(sigParts.join(' '));
   188→    this.indent();
   189→
   190→    // 1-pass: let 선언 수집 → (local ...) 선언
   191→    const locals = this.collectLocals(fn.body);
   192→    for (const [name, wt] of locals) {
   193→      this.emit(`(local $${name} ${wt})`);
   194→      this.localTypes.set(name, wt);
   195→    }
   196→
   197→    // 2-pass: 함수 본문 생성
   198→    for (const stmt of fn.body) {
   199→      this.genStatement(stmt);
   200→    }
   201→
   202→    this.dedent();
   203→    this.emit(')');
   204→
   205→    // export (모든 V 함수를 public export)
   206→    this.emit(`(export "${fn.name}" (func $${fn.name}))`);
   207→    this.exports.push(fn.name);
   208→  }
   209→
   210→  // ─── 로컬 변수 수집 (1-pass) ─────────────────────────────────────────────────
   211→
   212→  /**
   213→   * 함수 본문의 모든 Assign 구문을 재귀 탐색해
   214→   * (local $name type) 선언 목록을 반환
   215→   */
   216→  private collectLocals(stmts: AST.Statement[]): Map<string, string> {
   217→    const result: Map<string, string> = new Map();
   218→    this.collectLocalsFromStmts(stmts, result);
   219→    return result;
   220→  }
   221→
   222→  private collectLocalsFromStmts(stmts: AST.Statement[], result: Map<string, string>): void {
   223→    for (const stmt of stmts) {
   224→      const s = stmt as any;
   225→      if (s.type === 'Assign') {
   226→        if (!this.paramNames.has(s.name) && !result.has(s.name)) {
   227→          // 타입 추론: 타입 어노테이션 > 값에서 추론
   228→          let wt = 'i64';
   229→          if (s.typeAnnotation) {
   230→            wt = toWasmType(s.typeAnnotation.replace('[]', '')) || 'i64';
   231→          } else if (s.value) {
   232→            wt = this.inferExprType(s.value);
   233→          }
   234→          result.set(s.name, wt);
   235→        }
   236→      } else if (s.type === 'IfStatement') {
   237→        this.collectLocalsFromStmts(s.thenBranch || [], result);
   238→        if (s.elseBranch) this.collectLocalsFromStmts(s.elseBranch, result);
   239→      } else if (s.type === 'WhileStatement') {
   240→        this.collectLocalsFromStmts(s.body || [], result);
   241→      } else if (s.type === 'ForStatement') {
   242→        // for 루프 변수
   243→        if (!this.paramNames.has(s.variable) && !result.has(s.variable)) {
   244→          result.set(s.variable, 'i64');
   245→        }
   246→        this.collectLocalsFromStmts(s.body || [], result);
   247→      } else if (s.type === 'MatchStatement') {
   248→        for (const arm of (s.arms || [])) {
   249→          this.collectLocalsFromStmts(arm.body || [], result);
   250→        }
   251→      }
   252→    }
   253→  }
   254→
   255→  /** 표현식에서 WASM 타입 추론 */
   256→  private inferExprType(expr: AST.Expression): string {
   257→    const e = expr as any;
   258→    if (!e) return 'i64';
   259→    switch (e.type) {
   260→      case 'Number':
   261→        return typeof e.value === 'number' && !Number.isInteger(e.value) ? 'f64' : 'i64';
   262→      case 'BinaryExpr':
   263→        if (['==','!=','<','>','<=','>=','&&','||'].includes(e.operator)) return 'i32';
   264→        return this.inferExprType(e.left);
   265→      case 'Identifier':
   266→        return this.localTypes.get(e.name) || 'i64';
   267→      default:
   268→        return 'i64';
   269→    }
   270→  }
   271→
   272→  // ─── 문장 생성 ───────────────────────────────────────────────────────────────
   273→
   274→  private genStatement(stmt: AST.Statement): void {
   275→    const s = stmt as any;
   276→    switch (s.type) {
   277→      case 'Return':
   278→        this.genReturn(s);
   279→        break;
   280→      case 'Assign':
   281→        this.genAssign(s);
   282→        break;
   283→      case 'ExprStatement':
   284→        this.genExprStatement(s);
   285→        break;
   286→      case 'IfStatement':
   287→        this.genIf(s);
   288→        break;
   289→      case 'WhileStatement':
   290→        this.genWhile(s);
   291→        break;
   292→      case 'ForStatement':
   293→        this.genFor(s);
   294→        break;
   295→      case 'Break':
   296→        this.genBreak();
   297→        break;
   298→      case 'Continue':
   299→        this.genContinue();
   300→        break;
   301→      default:
   302→        this.warnings.push(`미지원 문장 타입: ${s.type} (스킵)`);
   303→    }
   304→  }
   305→
   306→  private genReturn(stmt: any): void {
   307→    if (stmt.value) {
   308→      this.genExpression(stmt.value);
   309→    }
   310→    this.emit('return');
   311→  }
   312→
   313→  private genAssign(stmt: any): void {
   314→    // local.set $name <expr>
   315→    this.genExpression(stmt.value);
   316→    this.emit(`local.set $${stmt.name}`);
   317→  }
   318→
   319→  private genExprStatement(stmt: any): void {
   320→    // 표현식 결과를 drop
   321→    this.genExpression(stmt.expression);
   322→    this.emit('drop');
   323→  }
   324→
   325→  private genIf(stmt: any): void {
   326→    // 조건 평가
   327→    this.genExpression(stmt.condition);
   328→
   329→    // if 블록 — 반환 타입은 우선 void로 처리
   330→    // (결과값이 필요한 if-expr는 미지원, 경고 생략)
   331→    this.emit('(if');
   332→    this.indent();
   333→    this.emit('(then');
   334→    this.indent();
   335→    for (const s of (stmt.thenBranch || [])) {
   336→      this.genStatement(s);
   337→    }
   338→    this.dedent();
   339→    this.emit(')');
   340→
   341→    if (stmt.elseBranch && stmt.elseBranch.length > 0) {
   342→      this.emit('(else');
   343→      this.indent();
   344→      for (const s of stmt.elseBranch) {
   345→        this.genStatement(s);
   346→      }
   347→      this.dedent();
   348→      this.emit(')');
   349→    }
   350→
   351→    this.dedent();
   352→    this.emit(')');
   353→  }
   354→
   355→  private genWhile(stmt: any): void {
   356→    const labelIdx = this.loopCounter++;
   357→    const outerLabel = `$while_outer_${labelIdx}`;
   358→    const innerLabel = `$while_inner_${labelIdx}`;
   359→
   360→    this.loopLabelStack.push({ breakLabel: outerLabel, continueLabel: innerLabel });
   361→
   362→    // block $while_outer (break 탈출 대상)
   363→    this.emit(`(block ${outerLabel}`);
   364→    this.indent();
   365→    // loop $while_inner (continue 대상)
   366→    this.emit(`(loop ${innerLabel}`);
   367→    this.indent();
   368→
   369→    // 조건 검사: 조건이 false(0)면 break
   370→    this.genExpression(stmt.condition);
   371→    this.emit('i32.eqz');
   372→    this.emit(`br_if ${outerLabel}`);
   373→
   374→    // 루프 본문
   375→    for (const s of (stmt.body || [])) {
   376→      this.genStatement(s);
   377→    }
   378→
   379→    // 루프 끝 → continue
   380→    this.emit(`br ${innerLabel}`);
   381→
   382→    this.dedent();
   383→    this.emit(')'); // loop 종료
   384→
   385→    this.dedent();
   386→    this.emit(')'); // block 종료
   387→
   388→    this.loopLabelStack.pop();
   389→  }
   390→
   391→  private genFor(stmt: any): void {
   392→    // for i in range(N) { body }
   393→    // → i = 0; while i < N { body; i++ }
   394→    const labelIdx = this.loopCounter++;
   395→    const outerLabel = `$for_outer_${labelIdx}`;
   396→    const innerLabel = `$for_inner_${labelIdx}`;
   397→
   398→    this.loopLabelStack.push({ breakLabel: outerLabel, continueLabel: innerLabel });
   399→
   400→    // 범위 상한 파악
   401→    let limit: AST.Expression | null = null;
   402→    const iterable = stmt.iterable as any;
   403→    if (iterable && iterable.type === 'Call') {
   404→      const callee = typeof iterable.callee === 'string' ? iterable.callee : (iterable.callee as any)?.name;
   405→      if (callee === 'range' && iterable.args.length >= 1) {
   406→        limit = iterable.args[0];
   407→      }
   408→    }
   409→
   410→    // 초기값: i = 0
   411→    this.emit(`i64.const 0`);
   412→    this.emit(`local.set $${stmt.variable}`);
   413→
   414→    // block/loop 구조
   415→    this.emit(`(block ${outerLabel}`);
   416→    this.indent();
   417→    this.emit(`(loop ${innerLabel}`);
   418→    this.indent();
   419→
   420→    // 조건: i < N
   421→    if (limit) {
   422→      this.emit(`local.get $${stmt.variable}`);
   423→      this.genExpression(limit);
   424→      this.emit('i64.ge_s');         // i >= limit → 탈출
   425→      this.emit(`br_if ${outerLabel}`);
   426→    }
   427→
   428→    // 루프 본문
   429→    for (const s of (stmt.body || [])) {
   430→      this.genStatement(s);
   431→    }
   432→
   433→    // i++
   434→    this.emit(`local.get $${stmt.variable}`);
   435→    this.emit('i64.const 1');
   436→    this.emit('i64.add');
   437→    this.emit(`local.set $${stmt.variable}`);
   438→
   439→    this.emit(`br ${innerLabel}`);
   440→
   441→    this.dedent();
   442→    this.emit(')'); // loop
   443→    this.dedent();
   444→    this.emit(')'); // block
   445→
   446→    this.loopLabelStack.pop();
   447→  }
   448→
   449→  private genBreak(): void {
   450→    if (this.loopLabelStack.length === 0) {
   451→      this.warnings.push('break가 루프 밖에서 사용됨 (스킵)');
   452→      return;
   453→    }
   454→    const top = this.loopLabelStack[this.loopLabelStack.length - 1];
   455→    this.emit(`br ${top.breakLabel}`);
   456→  }
   457→
   458→  private genContinue(): void {
   459→    if (this.loopLabelStack.length === 0) {
   460→      this.warnings.push('continue가 루프 밖에서 사용됨 (스킵)');
   461→      return;
   462→    }
   463→    const top = this.loopLabelStack[this.loopLabelStack.length - 1];
   464→    this.emit(`br ${top.continueLabel}`);
   465→  }
   466→
   467→  // ─── 표현식 생성 ─────────────────────────────────────────────────────────────
   468→
   469→  /**
   470→   * 표현식 → 스택에 값을 push하는 WAT 명령 생성
   471→   * WAT는 스택 기반이므로 각 표현식은 스택에 정확히 1개의 값을 남겨야 함
   472→   */
   473→  private genExpression(expr: AST.Expression): void {
   474→    const e = expr as any;
   475→    switch (e.type) {
   476→      case 'Number':
   477→        this.genNumber(e);
   478→        break;
   479→      case 'Identifier':
   480→        this.genIdentifier(e);
   481→        break;
   482→      case 'BinaryExpr':
   483→        this.genBinaryExpr(e);
   484→        break;
   485→      case 'Call':
   486→        this.genCall(e);
   487→        break;
   488→      case 'String':
   489→        // 문자열은 WASM 선형 메모리 없이 지원 불가 → 경고 후 0 push
   490→        this.warnings.push(`문자열 리터럴 "${e.value}"은 현재 WASM 미지원 (i64.const 0으로 대체)`);
   491→        this.emit('i64.const 0');
   492→        break;
   493→      default:
   494→        this.warnings.push(`미지원 표현식 타입: ${e.type} (i64.const 0으로 대체)`);
   495→        this.emit('i64.const 0');
   496→    }
   497→  }
   498→
   499→  private genNumber(expr: any): void {
   500→    const v = expr.value;
   501→    const numVal = typeof v === 'string'
   502→      ? (v.startsWith('0x') ? parseInt(v, 16) : parseFloat(v))
   503→      : v;
   504→
   505→    if (!Number.isInteger(numVal)) {
   506→      this.emit(`f64.const ${numVal}`);
   507→    } else {
   508→      this.emit(`i64.const ${numVal}`);
   509→    }
   510→  }
   511→
   512→  private genIdentifier(expr: any): void {
   513→    // 매개변수든 로컬 변수든 local.get 사용
   514→    this.emit(`local.get $${expr.name}`);
   515→  }
   516→
   517→  private genBinaryExpr(expr: any): void {
   518→    // 왼쪽 피연산자
   519→    this.genExpression(expr.left);
   520→    // 오른쪽 피연산자
   521→    this.genExpression(expr.right);
   522→
   523→    // 결과 타입 추론
   524→    const leftType = this.inferExprType(expr.left);
   525→    const opcode = wasmBinOp(expr.operator, leftType);
   526→    this.emit(opcode);
   527→  }
   528→
   529→  private genCall(expr: any): void {
   530→    const callee = typeof expr.callee === 'string'
   531→      ? expr.callee
   532→      : (expr.callee as any)?.name || '';
   533→
   534→    // 인자 순서대로 스택에 push
   535→    for (const arg of (expr.args || [])) {
   536→      this.genExpression(arg);
   537→    }
   538→
   539→    // 내장 함수 처리
   540→    switch (callee) {
   541→      case 'println':
   542→      case 'print':
   543→        // WASM에서 I/O는 import 필요 → 경고 후 인자 drop
   544→        this.warnings.push(`'${callee}'은 WASM에서 host import 필요. 현재 인자 drop 처리.`);
   545→        for (let i = 0; i < (expr.args || []).length; i++) {
   546→          this.emit('drop');
   547→        }
   548→        break;
   549→      case 'abs':
   550→        // i64.abs 없음 → 수동 구현: max(x, -x)
   551→        this.warnings.push(`abs()는 WASM에 i64.abs 미지원. 자체 구현(max(x,-x))으로 대체.`);
   552→        // 스택에 x가 있음. x, -x 중 max 선택
   553→        // 아래는 단순화: 이미 arg를 push했으므로 재사용 불가 → local 임시 변수 필요
   554→        // 현재 구현에서는 경고 후 그대로 통과 (정확하지 않음)
   555→        break;
   556→      default:
   557→        // 사용자 정의 함수 호출
   558→        this.emit(`call $${callee}`);
   559→        break;
   560→    }
   561→  }
   562→}
