export interface WasmCodegenResult {
  /** WAT (WebAssembly Text Format) 텍스트 */
  wat: string;
  /** export된 함수 이름 목록 */
  exports: string[];
  /** 경고 메시지 (미지원 기능 등) */
  warnings: string[];
  /** 문자열 상수 메모리 맵: string value → {offset, length} */
  stringTable: Map<string, { offset: number; length: number }>;
}

// ─── 문자열 관련 헬퍼 ────────────────────────────────────────────────────────

/**
 * 문자열을 WAT data 섹션 이스케이프 형식으로 변환
 * 예: "hello\n" → "hello\n" (WAT에서 \n은 \0a)
 */
function stringToWatData(s: string): string {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 0x0a) result += '\\0a';       // newline
    else if (c === 0x0d) result += '\\0d';  // carriage return
    else if (c === 0x22) result += '\\22';  // double quote
    else if (c === 0x5c) result += '\\5c';  // backslash
    else if (c >= 0x20 && c < 0x7f) result += s[i]; // printable ASCII
    else result += `\\${c.toString(16).padStart(2, '0')}`;
  }
  return result;
}

/** UTF-8 바이트 길이 계산 (ASCII만 지원, 확장은 향후) */
function utf8ByteLength(s: string): number {
  // For simplicity, count actual bytes including \n etc
  return s.length; // ASCII-only assumption for WAT data
}

