/**
 * Program AST → WAT 생성
 * Python 모드 함수, LangBlock 등은 스킵 (경고만 기록)
 */
generate(program: AST.Program): WasmCodegenResult {
  this.reset();

  // Phase N.4.3: 1차 패스 — 문자열 상수 수집 (data 섹션 레이아웃 결정)
  this.scanStrings(program);

  // module 시작
  this.emit('(module');
  this.indentLevel++;

  // Phase N.4.3: 문자열 사용 시 memory & host_print import 추가
  if (this.usesStrings) {
    this.emit('(memory (export "memory") 1)');
    // host_print(ptr: i32, len: i32) — 호스트 환경(Node.js/WASI)에서 구현
    this.emit('(import "env" "host_print" (func $host_print (param i32 i32)))');
  }

  let hasFunctions = false;
  for (const node of program.body) {
    const n = node as any;
    if (n.type === 'VFunction') {
      this.genVFunction(n as AST.VFunction);
      hasFunctions = true;
    } else if (n.type === 'PyFunction') {
      this.warnings.push(`Python 모드 함수 '${(n as AST.PyFunction).name}'은 WASM 미지원 (스킵)`);
    } else if (n.type === 'StructDef') {
      this.warnings.push(`구조체 '${(n as AST.StructDef).name}'은 현재 WASM 미지원 (스킵)`);
    } else if (n.type === 'LangBlock') {
      this.warnings.push(`@lang 블록은 WASM 미지원 (스킵)`);
    } else if (n.type === 'ExternCall') {
      this.warnings.push(`@call 지시문은 WASM 미지원 (스킵)`);
    }
    // 그 외 탑레벨 구문은 무시
  }

  if (!hasFunctions) {
    this.warnings.push('V 모드 함수가 없습니다. 빈 모듈이 생성됩니다.');
  }

  // Phase N.4.3: (data ...) 섹션 생성
  if (this.usesStrings) {
    for (const [strVal, { offset }] of this.stringTable) {
      const escaped = stringToWatData(strVal);
      this.emit(`(data (i32.const ${offset}) "${escaped}")`);
    }
  }

  this.indentLevel--;
  this.emit(')');

  return {
    wat: this.lines.join('\n'),
    exports: [...this.exports],
    warnings: [...this.warnings],
    stringTable: new Map(this.stringTable),
  };
}

// ─── Phase N.4.3: 문자열 스캔 ────────────────────────────────────────────────

/**
 * 프로그램 전체에서 문자열 리터럴을 수집하여 stringTable을 구성합니다.
 * 중복 문자열은 한 번만 저장 (중복 제거).
 */
private scanStrings(program: AST.Program): void {
  for (const node of program.body) {
    const n = node as any;
    if (n.type === 'VFunction') {
      this.scanStringsInStmts((n as AST.VFunction).body);
    }
  }
}

private scanStringsInStmts(stmts: AST.Statement[]): void {
  for (const stmt of stmts) {
    const s = stmt as any;
    switch (s.type) {
      case 'Return':
        if (s.value) this.scanStringsInExpr(s.value);
        break;
      case 'Assign':
        this.scanStringsInExpr(s.value);
        break;
      case 'ExprStatement':
        this.scanStringsInExpr(s.expression);
        break;
      case 'IfStatement':
        this.scanStringsInExpr(s.condition);
        this.scanStringsInStmts(s.thenBranch || []);
        if (s.elseBranch) this.scanStringsInStmts(s.elseBranch);
        break;
      case 'WhileStatement':
        this.scanStringsInExpr(s.condition);
        this.scanStringsInStmts(s.body || []);
        break;
      case 'ForStatement':
        this.scanStringsInStmts(s.body || []);
        break;
    }
  }
}

private scanStringsInExpr(expr: AST.Expression): void {
  const e = expr as any;
  if (!e) return;
  switch (e.type) {
    case 'String':
      this.registerString(e.value as string);
      break;
    case 'BinaryExpr':
      this.scanStringsInExpr(e.left);
      this.scanStringsInExpr(e.right);
      break;
    case 'Call':
      for (const arg of (e.args || [])) {
        this.scanStringsInExpr(arg);
      }
      break;
  }
}

/**
 * 문자열 상수를 stringTable에 등록.
 * 이미 등록된 문자열은 중복 추가하지 않음.
 */
private registerString(s: string): void {
  if (this.stringTable.has(s)) return;
  const length = utf8ByteLength(s);
  this.stringTable.set(s, { offset: this.stringOffset, length });
  this.stringOffset += length;
  this.usesStrings = true;
}

/**
 * 문자열의 메모리 포인터(오프셋)를 i32.const로 스택에 push
 */
private emitStringPtr(s: string): void {
  const entry = this.stringTable.get(s);
  if (entry) {
    this.emit(`i32.const ${entry.offset}  ;; ptr "${s.substring(0, 20)}"`);
  } else {
    this.emit('i32.const 0  ;; unknown string ptr');
  }
}

/**
 * 문자열의 길이를 i32.const로 스택에 push
 */
private emitStringLen(s: string): void {
  const entry = this.stringTable.get(s);
  if (entry) {
    this.emit(`i32.const ${entry.length}  ;; len "${s.substring(0, 20)}"`);
  } else {
    this.emit('i32.const 0  ;; unknown string len');
  }
}

