private genCall(expr: any): void {
  const callee = typeof expr.callee === 'string'
    ? expr.callee
    : (expr.callee as any)?.name || '';

  // 인자 순서대로 스택에 push
  for (const arg of (expr.args || [])) {
    this.genExpression(arg);
  }

  // 내장 함수 처리
  switch (callee) {
    case 'println':
    case 'print':
      // WASM에서 I/O는 import 필요 → 경고 후 인자 drop
      this.warnings.push(`'${callee}'은 WASM에서 host import 필요. 현재 인자 drop 처리.`);
      for (let i = 0; i < (expr.args || []).length; i++) {
        this.emit('drop');
      }
      break;
    case 'abs':
      // i64.abs 없음 → 수동 구현: max(x, -x)
      this.warnings.push(`abs()는 WASM에 i64.abs 미지원. 자체 구현(max(x,-x))으로 대체.`);
      // 스택에 x가 있음. x, -x 중 max 선택
      // 아래는 단순화: 이미 arg를 push했으므로 재사용 불가 → local 임시 변수 필요
      // 현재 구현에서는 경고 후 그대로 통과 (정확하지 않음)
      break;
    default:
      // 사용자 정의 함수 호출
      this.emit(`call $${callee}`);
      break;
  }
}

