private genCall(expr: any): void {
  const callee = typeof expr.callee === 'string'
    ? expr.callee
    : (expr.callee as any)?.name || '';

  // 내장 함수 처리
  switch (callee) {
    case 'println':
    case 'print': {
      // Phase N.4.3: 문자열 인자가 있으면 host_print(ptr, len) 호출
      const args: any[] = expr.args || [];
      if (args.length === 1 && args[0].type === 'String') {
        // 문자열 상수 println → host_print(ptr, len) + newline
        const strVal = args[0].value as string;
        const hasNewline = callee === 'println';

        if (hasNewline) {
          // println: "hello\n" 형태로 미리 등록 (스캔 시 이미 등록됨)
          // ptr, len을 push하고 host_print 호출
          this.emitStringPtr(strVal);
          this.emitStringLen(strVal);
          this.emit('call $host_print');
        } else {
          // print: 마찬가지로 ptr, len push
          this.emitStringPtr(strVal);
          this.emitStringLen(strVal);
          this.emit('call $host_print');
        }
      } else if (args.length > 0) {
        // 문자열이 아닌 인자: 인자를 평가 후 drop (I/O 미지원)
        this.warnings.push(`'${callee}'은 비문자열 인자에 대해 drop 처리됩니다.`);
        for (const arg of args) {
          this.genExpression(arg);
          this.emit('drop');
        }
      } else {
        // 인자 없는 println
        this.warnings.push(`'${callee}' 인자 없음 — 스킵.`);
      }
      break;
    }
    case 'str_ptr': {
      // Phase N.4.3: str_ptr(str) → i32 메모리 포인터 반환
      const args: any[] = expr.args || [];
      if (args.length === 1 && args[0].type === 'String') {
        this.emitStringPtr(args[0].value as string);
      } else {
        this.emit('i32.const 0  ;; str_ptr: 문자열 상수만 지원');
      }
      break;
    }
    case 'str_len': {
      // Phase N.4.3: str_len(str) → i32 문자열 길이 반환
      const args: any[] = expr.args || [];
      if (args.length === 1 && args[0].type === 'String') {
        this.emitStringLen(args[0].value as string);
      } else {
        this.emit('i32.const 0  ;; str_len: 문자열 상수만 지원');
      }
      break;
    }
    case 'abs':
      // i64.abs 없음 → 수동 구현: max(x, -x)
      this.warnings.push(`abs()는 WASM에 i64.abs 미지원. 자체 구현(max(x,-x))으로 대체.`);
      // 인자 순서대로 스택에 push
      for (const arg of (expr.args || [])) {
        this.genExpression(arg);
      }
      break;
    default:
      // 인자 순서대로 스택에 push
      for (const arg of (expr.args || [])) {
        this.genExpression(arg);
      }
      // 사용자 정의 함수 호출
      this.emit(`call $${callee}`);
      break;
  }
}

