/** FreeLang 타입 → WASM 타입 */
function toWasmType(flType: string | undefined): string {
  if (!flType) return 'i64'; // 기본값
  switch (flType.trim()) {
    case 'i64': return 'i64';
    case 'f64': return 'f64';
    case 'f32': return 'f32';
    case 'i32': return 'i32';
    case 'bool': return 'i32'; // bool → i32 (WASM에 bool 없음)
    case 'void': return '';    // 반환 없음
    default: return 'i64';     // 미지원 타입은 i64 폴백
  }
}

