/** 표현식에서 WASM 타입 추론 */
private inferExprType(expr: AST.Expression): string {
  const e = expr as any;
  if (!e) return 'i64';
  switch (e.type) {
    case 'Number':
      return typeof e.value === 'number' && !Number.isInteger(e.value) ? 'f64' : 'i64';
    case 'BinaryExpr':
      if (['==','!=','<','>','<=','>=','&&','||'].includes(e.operator)) return 'i32';
      return this.inferExprType(e.left);
    case 'Identifier':
      return this.localTypes.get(e.name) || 'i64';
    default:
      return 'i64';
  }
}

