/** 표현식에서 WASM 타입 추론 */
private inferExprType(expr: AST.Expression): string {
  const e = expr as any;
  if (!e) return 'i64';
  switch (e.type) {
    case 'Number':
      return typeof e.value === 'number' && !Number.isInteger(e.value) ? 'f64' : 'i64';
    case 'String':
      return 'i32'; // Phase N.4.3: 문자열 리터럴 → i32 포인터
    case 'BinaryExpr':
      if (['==','!=','<','>','<=','>=','&&','||'].includes(e.operator)) return 'i32';
      return this.inferExprType(e.left);
    case 'Identifier':
      return this.localTypes.get(e.name) || 'i64';
    case 'Call': {
      const callee = typeof e.callee === 'string' ? e.callee : (e.callee as any)?.name || '';
      if (callee === 'str_ptr' || callee === 'str_len') return 'i32';
      return 'i64';
    }
    default:
      return 'i64';
  }
}

