/**
 * FreeLang Nexus - WebAssembly 고급 기능 테스트
 *
 * Phase N.4.3 — string 타입 지원 (WAT data 섹션)
 *
 * 테스트 범위:
 *  1.  string 파라미터 → i32 타입 변환
 *  2.  string 반환 타입 → i32 타입 변환
 *  3.  string 리터럴 → (data ...) 섹션 생성
 *  4.  string 리터럴 → i32.const (ptr) 스택 push
 *  5.  println(str) → call $host_print 생성
 *  6.  memory 선언 생성 (string 사용 시)
 *  7.  host_print import 선언 생성
 *  8.  중복 문자열 → 단일 data 섹션 항목
 *  9.  여러 문자열 → 연속 오프셋 배치
 * 10.  str_ptr(str) → i32.const 오프셋 반환
 * 11.  str_len(str) → i32.const 길이 반환
 * 12.  string 미사용 시 memory 선언 없음
 * 13.  string 미사용 시 host_print import 없음
 * 14.  stringTable exports 구조 확인
 * 15.  빈 문자열 → length 0 data 섹션
 * 16.  string 타입 로컬 변수 → (local $x i32) 선언
 * 17.  string 파라미터 오프셋 data 섹션 순서
 * 18.  println 없는 string 참조 → ptr 반환
 * 19.  여러 함수에서 동일 문자열 공유
 * 20.  exports 배열에 string 함수명 포함
 */

import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusWasmCodegen, WasmCodegenResult } from '../src/nexus/codegen/nexus-wasm-codegen';

// ─── 헬퍼 ────────────────────────────────────────────────────────────────────

function compileWat(code: string): WasmCodegenResult {
  const lexer = new NexusLexer(code);
  const tokens = lexer.tokenize();
  const parser = new NexusParser(tokens);
  const ast = parser.parse();
  const gen = new NexusWasmCodegen();
  return gen.generate(ast);
}

function wat(code: string): string {
  return compileWat(code).wat;
}

// ─── 1. string 타입 변환 ──────────────────────────────────────────────────────

describe('Phase N.4.3 — string 타입 변환', () => {
  test('Test 1: string 파라미터 → i32 타입', () => {
    const result = wat(`@mode(v)
fn greet(msg: string) -> i64 {
  return 0
}`);
    expect(result).toContain('(param $msg i32)');
  });

  test('Test 2: string 반환 타입 → i32 타입', () => {
    const result = wat(`@mode(v)
fn get_msg() -> string {
  return 0
}`);
    expect(result).toContain('(result i32)');
  });

  test('Test 3: string 타입 로컬 변수 → (local $s i32)', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  let s: string = "hello"
  return 0
}`);
    expect(result).toContain('(local $s i32)');
  });
});

// ─── 2. data 섹션 생성 ────────────────────────────────────────────────────────

describe('Phase N.4.3 — (data ...) 섹션', () => {
  test('Test 4: 문자열 리터럴 → (data ...) 섹션 생성', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("hello")
  return 0
}`);
    expect(result).toContain('(data');
    expect(result).toContain('"hello"');
  });

  test('Test 5: 중복 문자열 → data 섹션에 1번만 등장', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("world")
  println("world")
  return 0
}`);
    // "world" 가 data 섹션에 정확히 한 번 등장해야 함
    const dataMatches = (result.match(/"world"/g) || []);
    // data 섹션에서 1번, i32.const 주석에서 추가 등장 가능
    // 최소 1번은 있어야 함
    expect(dataMatches.length).toBeGreaterThanOrEqual(1);
  });

  test('Test 6: 여러 문자열 → 각각 data 섹션에 포함', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("alpha")
  println("beta")
  return 0
}`);
    expect(result).toContain('"alpha"');
    expect(result).toContain('"beta"');
  });

  test('Test 7: data 섹션은 module 내부에 위치', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("hi")
  return 0
}`);
    // (module 이 먼저, ) 가 마지막
    const moduleIdx = result.indexOf('(module');
    const dataIdx = result.indexOf('(data');
    const closingIdx = result.lastIndexOf(')');
    expect(moduleIdx).toBeLessThan(dataIdx);
    expect(dataIdx).toBeLessThan(closingIdx);
  });
});

// ─── 3. memory & import 선언 ─────────────────────────────────────────────────

describe('Phase N.4.3 — memory & import', () => {
  test('Test 8: string 사용 시 memory 선언 생성', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("hello")
  return 0
}`);
    expect(result).toContain('(memory');
  });

  test('Test 9: string 사용 시 host_print import 선언', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("hello")
  return 0
}`);
    expect(result).toContain('$host_print');
    expect(result).toContain('(import');
  });

  test('Test 10: string 미사용 시 memory 선언 없음', () => {
    const result = wat(`@mode(v)
fn add(a: i64, b: i64) -> i64 {
  return a + b
}`);
    expect(result).not.toContain('(memory');
  });

  test('Test 11: string 미사용 시 host_print import 없음', () => {
    const result = wat(`@mode(v)
fn mul(a: i64, b: i64) -> i64 {
  return a * b
}`);
    expect(result).not.toContain('host_print');
  });
});

// ─── 4. println 코드 생성 ─────────────────────────────────────────────────────

describe('Phase N.4.3 — println 코드 생성', () => {
  test('Test 12: println(str) → call $host_print 생성', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("hello world")
  return 0
}`);
    expect(result).toContain('call $host_print');
  });

  test('Test 13: println(str) → i32.const (ptr) 스택에 push', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("nexus")
  return 0
}`);
    // i32.const <offset> 형태 존재 확인
    expect(result).toMatch(/i32\.const \d+/);
  });

  test('Test 14: println(str) → ptr와 len 두 개의 i32.const', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  println("hi")
  return 0
}`);
    // ptr(i32.const N)과 len(i32.const 2) 두 개
    const i32consts = (result.match(/i32\.const \d+/g) || []);
    expect(i32consts.length).toBeGreaterThanOrEqual(2);
  });
});

// ─── 5. str_ptr / str_len 헬퍼 ───────────────────────────────────────────────

describe('Phase N.4.3 — str_ptr / str_len', () => {
  test('Test 15: str_len("hello") → i32.const 5', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  let n = str_len("hello")
  return 0
}`);
    expect(result).toContain('i32.const 5');
  });

  test('Test 16: str_ptr("hi") → i32.const (오프셋)', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  let p = str_ptr("hi")
  return 0
}`);
    // i32.const 0 (첫 번째 문자열은 오프셋 0)
    expect(result).toMatch(/i32\.const \d+/);
  });

  test('Test 17: str_len("freelang") → i32.const 8', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  let n = str_len("freelang")
  return 0
}`);
    expect(result).toContain('i32.const 8');
  });
});

// ─── 6. stringTable API ───────────────────────────────────────────────────────

describe('Phase N.4.3 — stringTable API', () => {
  test('Test 18: stringTable은 Map 타입', () => {
    const result = compileWat(`@mode(v)
fn test() -> i64 {
  println("hello")
  return 0
}`);
    expect(result.stringTable).toBeInstanceOf(Map);
  });

  test('Test 19: stringTable에 사용된 문자열 포함', () => {
    const result = compileWat(`@mode(v)
fn test() -> i64 {
  println("greet")
  return 0
}`);
    expect(result.stringTable.has('greet')).toBe(true);
  });

  test('Test 20: 여러 함수에서 동일 문자열 → stringTable에 1번만', () => {
    const result = compileWat(`@mode(v)
fn a() -> i64 {
  println("shared")
  return 0
}
fn b() -> i64 {
  println("shared")
  return 0
}`);
    // 중복 제거: "shared"는 1번만
    expect(result.stringTable.size).toBe(1);
    expect(result.stringTable.has('shared')).toBe(true);
  });
});

