/** UTF-8 바이트 길이 계산 (ASCII만 지원, 확장은 향후) */
function utf8ByteLength(s: string): number {
  // For simplicity, count actual bytes including \n etc
  return s.length; // ASCII-only assumption for WAT data
}

/**
 * 파서가 저장하는 문자열 값(따옴표 포함)에서 실제 내용을 추출합니다.
 * "\"hello\"" → "hello"
 * "hello" (따옴표 없음) → "hello"
 */
function unquoteString(s: string): string {
  if (s.length >= 2 && s.startsWith('"') && s.endsWith('"')) {
    return s.slice(1, -1);
  }
  if (s.length >= 2 && s.startsWith("'") && s.endsWith("'")) {
    return s.slice(1, -1);
  }
